/* ================= THEME 2 · READING 3 · Patall et al. (2022) ================= */
/* board helper: a badge for the kind of motivation, and the practices of its table lighting up */
function PBOARD(S,B,chips,lit){const g=S.got,on=k=>S.end||Object.keys(lit).some(r=>g[r]&&[].concat(lit[r]).includes(k));
 let s=BX(12,58,150,192,B[3],B[2],2)+`<text x="87" y="112" ${mid} font-size="34">${B[0]}</text>`+TL(87,144,B[1],`${mid} font-weight="700" font-size="12.5" fill="${B[2]}"`,16)+TL(87,196,B[4],`${mid} class="t-s" font-size="10.5"`,14);
 const rows=Math.ceil(chips.length/2),h=Math.min(58,(192-(rows-1)*8)/rows);
 chips.forEach((c,j)=>{const x=172+(j%2)*230,y=58+Math.floor(j/2)*(h+8),o=on(c[0]);s+=BX(x,y,222,h,o?B[3]:'#fff',o?B[2]:'#c9cfd9',o?2:1.3,12)+`<text x="${x+26}" y="${y+h/2+8}" ${mid} font-size="20">${c[1]}</text>`+TL(x+48,y+h/2+(c[2].length>1?-3:4),c[2],`font-weight="700" font-size="11.5" fill="${o?B[2]:'#9aa3ad'}"`,14)});
 return s}

/* ---------- step 2 · the map: five supports ---------- */
(function(){
const Z={co:['💪',['"I can','do this"'],'Perceived competence','Table 1','#34466b','#e3ecf7',12,58],au:['🗝️',['"This is','my own"'],'Autonomy','Table 2','#6d5a9e','#efeaf7',220,58],va:['✨',['"This matters,','this grabs me"'],'Value and interest','Table 3','#2f8a57','#e2f1e6',428,58],
 gr:['🌱',['"I can grow, and','I am here to learn"'],'Growth and mastery goals','Table 4','#a8854a','#f6eedd',116,158],be:['🤝',['"I belong','here"'],'Relatedness and belonging','Table 5','#4f6aa0','#e3ecf7',324,158]};
const mv=(k,c,say)=>({k,ic:'🧑‍🏫',c,pick:k,hint:'Which feeling in the student does this practice mainly support? Tap a tile.',say});
SEQ('pracMap','pmOut',{title:'Five things a teacher can support',hook:'Hook: can · own · matters · grow · belong',unit:'Practice',cue:'Tap the tile above that this practice mainly supports',
 draw(S){let s='';Object.keys(Z).forEach(k=>{const [ic,pl,nm,tb,c,f,x,y]=Z[k],on=S.got[k]||S.end;
   s+=`<g ${S.z(k)}>${BX(x,y,200,90,on?f:'#fff',on?c:'#c9cfd9',on?2.4:1.5)}<text x="${x+28}" y="${y+42}" ${mid} font-size="24">${ic}</text>`+TL(x+52,y+(on?24:36),pl,`font-weight="700" font-size="12" fill="#34466b"`,15)+(on?`<text x="${x+52}" y="${y+62}" font-weight="700" font-size="${nm.length>24?10.5:11.5}" fill="${c}">${nm}</text><text x="${x+52}" y="${y+78}" class="t-s" font-size="10.5">${tb}</text>`:'')+'</g>'});return s},
 rounds:shuf([
 mv('co',['The teacher sets clear, consistent expectations, rules','and routines, so students know what to do to succeed.'],`<b>💪 Perceived competence (Table 1).</b> A well-structured classroom gives predictability and a feeling of control, which supports students' belief that they can succeed. <b>Competence beliefs</b> are positive self-assessments of one's ability and likelihood of succeeding at a task.`),
 mv('au',['The teacher lets students choose the topic of their','report and how they will present it.'],`<b>🗝️ Autonomy (Table 2).</b> Choice gives students a sense that they have freedom and can do what they like and value. <b>Autonomy</b> is the feeling that your actions come from and fit with yourself.`),
 mv('va',['Before the lesson, the teacher explains how this statistics','topic will help the students in their own future work.'],`<b>✨ Value and interest (Table 3).</b> This is a <b>rationale</b>: an explanation of why an activity is useful or important. It highlights the value of the activity, so the student wants to engage. The chapter also discusses rationales under autonomy, and Table 3 lists autonomy as something rationales can also support; the table they sit in is Table 3.`),
 mv('gr',['The teacher gives a short lesson on how the brain builds','ability when it does challenging work.'],`<b>🌱 Growth mindset and mastery goals (Table 4).</b> This is <b>mindset training</b>: conveying that intelligence is malleable and can grow with effort. It gives students a reason to put in effort and to persist when things are hard.`),
 mv('be',['The teacher tells new students: "Feeling out of place at','first is common, and it passes."'],`<b>🤝 Relatedness and belonging (Table 5).</b> A message that communicates belonging: the student belongs here, and worries about not fitting in are common and temporary.`)]).concat([
 {k:'ov',ic:'🔀',c:['Each table in the chapter has a last column:','"Can also support …".'],q:'Does a practice usually support only one kind of motivation?',o:[['No: one practice often','supports several'],['Yes: one practice,','one kind']],say:`<b>Extensive overlap.</b> Providing choices, for example, primarily supports autonomy, but can also support competence beliefs, interest and value, mastery goals and belonging. The authors call this overlap a good thing: there are many pathways to motivation. The other side: rarely will one practice fully support the motivation needs of a class, or even of one student.`}]),
 end:['Five sets of practices, one per kind of adaptive motivation.','The next five steps open them one at a time.'],
 endOut:`<b>🏁 The five design principles.</b> The authors could have made a longer list, but chose five categories on purpose: for readers who try to understand how to support students' motivation, they believe "less is more".`,
 extras:[['📚 Which theories sit behind each?',`<b>Competence:</b> self-efficacy (social cognitive theory), expectancies (expectancy-value theory), academic self-concept, the need for competence (self-determination theory), goal-setting theory. <b>Autonomy:</b> self-determination theory, social cognitive theory (agency), stage-environment fit. <b>Value and interest:</b> expectancy-value theory, self-determination theory, interest theories, culturally relevant education. <b>Growth and mastery:</b> attribution theory, mindsets, achievement goal theory. <b>Belonging:</b> attachment theory, self-determination theory, the belongingness hypothesis. You met most of these in reading 1.`]]});
})();

/* ---------- step 3 · perceived competence ---------- */
SEQ('pracComp','pcOut',{title:'Support the feeling "I can do this"',hook:'Hook: clear · stretching · informative · someone like me · strategies',unit:'Case',
 draw(S){return PBOARD(S,['💪',['Perceived','competence'],'#34466b','#e3ecf7',['Table 1']],[['st','📐',['Structure, climate','and norms']],['ch','🧗',['Appropriate challenge','and scaffolding']],['fb','💬',['Informational feedback,','praise, persuasion']],['mo','👀',['Modeling and','vicarious learning']],['sr','🧭',['Self-regulation','instruction']]],{fr:'st',fu:'st',ea:'ch',wi:'fb',ls:'mo',tk:'sr'})},
 rounds:[
 {k:'fr',ic:'📐',c:['Freiberg, Stein and Huang (1995) trained urban elementary school','teachers in classroom management, particularly in setting','clear rules, and compared their students with other students.'],q:'What changed for the students of the trained teachers?',o:[['Higher self-concept,','expectancies, test scores'],['Better behaviour,','nothing else'],['Lower confidence:','too many rules']],say:`<b>Clear structure builds confidence.</b> Training led to enhanced academic self-concept and expectancies, as well as standardized test scores, relative to comparison students. Students feel more confident where there are clear parameters for behaviour and reliable, consistent teacher responses. Likewise, students who perceived clear expectations together with high autonomy support reported higher motivation and more adaptive strategy use (Vansteenkiste et al., 2012). One condition: clear expectations support perceived competence most when they are presented in an autonomy-supportive way, so that students experience them as informational, not controlling.`},
 {k:'ea',ic:'🧗',c:['Ms Rossi wants Leo to feel successful. She gives him very easy','tasks and a lot of help, so that he always gets them right.'],q:'What does this do to Leo\'s belief in his own ability?',o:[['It can undermine it'],['It builds it: success','is success'],['Nothing']],say:`<b>Easy success is not a mastery experience.</b> A task that is too easy, or that comes with too much help, does not give a student a mastery experience, even when she completes it. Students are often aware of the lack of challenge and can read it as a sign that the teacher lacks confidence in their abilities. This is especially problematic for minoritized students and students underrepresented in a field, because it may reinforce the low expectations and stereotypes they already meet. What works: tasks calibrated to existing skills with challenges that slightly exceed them, plus <b>scaffolding</b> (hints, cues, examples, breaking a task into manageable pieces) and difficulty that increases step by step. (Ms Rossi and Leo are our example.)`},
 {k:'wi',ic:'💬',c:['Yeager and colleagues (2014): middle schoolers got critical','feedback on their work. For some, the teacher added that the comments','came from high expectations and confidence that they could meet them.'],q:'For which students was the effect of this "wise feedback" strongest?',o:[['African American students,','most with mistrust of school'],['White','students'],['The same','for all']],say:`<b>Wise feedback.</b> Students who received it were more likely to revise their work and ultimately achieved at a higher level, with stronger effects for African American students compared with their white peers, particularly those who reported greater mistrust in school. The authors' explanation: marginalized students are at greater risk of interpreting critical feedback through the lens of racism and low-ability stereotypes, so the framing matters. University students who received feedback aligned with clear task criteria performed better, and lower performers among them reported higher motivation (Wilbert et al., 2010). In general, feedback should be informational: what went well, why, and how to improve, against absolute standards and not in comparison with classmates.`},
 {k:'ls',ic:'👀',c:['Lin-Siegler and colleagues (2016): 9th- and 10th-grade students','read stories about prominent scientists. In one group the','stories told how the scientists struggled and overcame challenges.'],q:'Compared with a control group, the "struggle story" students:',o:[['Performed better and felt more','connected to the scientists'],['Felt discouraged: even','geniuses struggle'],['Showed no','difference']],say:`<b>Show the struggle, not only the result.</b> Effective modeling includes demonstrations of responding to struggle as part of learning. Seeing only ideal models can undermine perceived competence, because the standard looks unreachable. Modeling helps most when the model is a peer or someone the student identifies with: when "someone like me" can do it, I can imagine doing it too. That may be especially critical for students from groups underrepresented in a field, such as women and minorities in science.`},
 {k:'fu',ic:'👥',c:['Fuchs and colleagues (2000) compared two ways of organizing','group work for lower-achieving students: pairs (dyads),','or small groups.'],q:'Which gave lower-achieving students more chances to collaborate?',o:[['Pairs'],['Small groups'],['No difference']],say:`<b>Pairs.</b> Dyads, compared with small groups, yielded more collaborative opportunities for lower-achieving students and better participation, helpfulness, cooperation and quality of talk overall. Mixed-ability groups with clear collaboration routines can foster the perceived competence of lower-achieving students. Ability grouping, in contrast, can undermine it by activating negative social comparisons. In general, practices that highlight relative ability and comparison between students can be detrimental to perceived competence, especially for lower-performing students.`},
 {k:'tk',ic:'🧭',c:['Tuckman and Kennedy (2011): first-year college students were','taught self-regulatory and learning strategies. They were','compared with matched peers who were not.'],q:'What was found, and for whom was the effect especially strong?',o:[['Higher grades and graduation;','strongest for low starters'],['Higher grades only for','the best students'],['No effect on','grades']],say:`<b>Strategy teaching went with better results.</b> The taught students had higher GPAs and higher retention and graduation rates than matched peers, with an especially strong effect for students with lower initial GPAs. The chapter's proposed mechanism is confidence; this study measured grades, retention and graduation. <b>Self-regulation instruction</b> means teaching students how to manage their own learning: goal-setting, activating prior knowledge, summarizing and paraphrasing, outlining, monitoring progress, and positive self-talk. It works best when it is built into regular lessons, so students practise the strategies in a real learning context.`}],
 end:['Students feel able when the class is clear, the work stretches them, feedback',' informs them, they see people like them succeed, and they know how to learn.'],
 endOut:`<b>🏁 Five practices from Table 1.</b> Together they feed the four sources of self-efficacy you met in reading 1. The authors stress that it is the student's <i>perception</i> of competence that matters most for choices and behaviour, more so than actual competence.`,
 extras:[['🧱 The four sources, with the chapter\'s own examples',`Self-concept differs from self-efficacy and expectancies: those two are beliefs about future competence in specific tasks or domains, while self-concept is a judgment about oneself across domains, in comparison with others and based on past performance. <b>Enactive mastery experiences:</b> a student completes a challenging maths problem successfully. <b>Vicarious experiences:</b> a student observes a similar peer complete it. <b>Verbal persuasion and social influences:</b> a teacher talks with the student about why she is confident that the student can learn to do it. <b>Physiological and affective states:</b> the student's positive emotions and calm body tell him he can do it. Reading 1 only named the four; this chapter defines them.`],['🙋 Help-seeking and climate',`An emotionally supportive climate with non-controlling, positive relationships also promotes perceived competence. Clear norms around help-seeking give students a way to get support and focus them on improvement instead of on avoiding embarrassment; normalizing help-seeking could also help offset stereotype threat in students from marginalized groups. Negative feedback is necessary but risky: teachers can soften the risk by tying criticism to the skill and not the person, using empathy and a warm tone, and giving clear tips and options for how to improve.`],['🎯 Goals',`Encouraging students to set their own specific, challenging but attainable goals supports perceived competence, especially when they can identify and achieve the interim steps. MBA students prompted to set specific and challenging learning goals, and those who had reflected on their purpose for entering the programme, had higher self-efficacy at the end of the year than students who set more distant goals (Latham &amp; Brown, 2006).`]]});

/* ---------- step 4 · autonomy ---------- */
SEQ('pracAut','paOut',{title:'Support the feeling "this is my own"',hook:'Hook: offer · listen · build in · invite · do not push · let them shape it',unit:'Case',
 draw(S){return PBOARD(S,['🗝️',['Autonomy'],'#6d5a9e','#efeaf7',['Table 2']],[['ch','🔀',['Choice','opportunities']],['pt','👂',['Perspective-taking']],['in','🧩',['Incorporating student','perspectives']],['rl','💬',['Respectful language']],['mc','🚫',['Minimizing controlling','language, practices']],['ag','🙋',['Encouraging','student agency']]],{wa:'ch',ma:'ch',cu:'ch',di:['pt','mc','rl'],ja:'in',ae:'ag'})},
 rounds:[
 {k:'wa',ic:'🎨',c:['Waterschoot and colleagues (2019): Belgian late elementary school','students could express which painting activity they preferred,','and got it. Others were simply told what to paint.'],q:'What did having a say lead to?',o:[['More autonomy and competence,','then more intrinsic motivation'],['More fun, but less','sense of competence'],['Nothing: painting','is painting']],say:`<b>Choice works.</b> Students given the opportunity reported an enhanced sense of autonomy and competence and, in turn, greater intrinsic motivation, vitality and intentions to persist at the activity, relative to students who were obliged by their teacher. Extensive experimental, correlational and meta-analytic evidence suggests benefits of choice for feelings of autonomy, interest, enjoyment, perceived competence, effort, persistence and performance. Choices can be about actions, assignments, pacing, tasks, topics, methods and classroom management; different types of choice do not appear to be uniformly more or less beneficial.`},
 {k:'ma',ic:'🗂️',c:['Our example: a teacher offers a choice of 24 essay topics that','all look very similar. The students do not yet know the subject well.'],q:'What does the research suggest about this choice?',o:[['It has fewer benefits and','needs guidance'],['The more options,','the better'],['It always','backfires']],say:`<b>Choosing costs effort.</b> Choice has fewer benefits when there are excessive options, when options are hard to tell apart, or when students feel indecisive. It can backfire when students do not know what makes a good choice or lack competence on the task. Then choices need clear expectations, guidelines or scaffolding, and students may prefer that a trusted teacher, peer or parent chooses for them. The key principle: having options, choosing, and <i>experiencing autonomy</i> are not the same thing, and only the last one is what matters for motivation. Choices given in a controlling way have more limited benefits.`},
 {k:'cu',ic:'🌏',c:['A student from a more collectivist cultural background','lets a trusted teacher pick her project topic for her.'],q:'According to the chapter, is that bad for her motivation?',o:[['No: it can be equally or','more motivating'],['Yes: only personal choice','supports autonomy']],say:`<b>Context changes what choosing means.</b> When the cultural context emphasizes a group orientation (the chapter names more collectivist cultures, including Asian and Latinx cultures), students may experience equal and sometimes greater benefits from deferring choice to trusted others (for example Bao &amp; Lam, 2008). To the extent that having someone else choose is itself perceived as an autonomous experience, it may be equally or more motivating than choosing personally.`},
 {k:'di',ic:'📓',c:['Patall and colleagues (2018) had urban high school students keep','a diary about their science lessons. On some days the teacher','used commands and "you must", and brushed opinions aside.'],q:'What happened on those days?',o:[['Disengagement','went up'],['Students worked','harder'],['Nothing: students','are used to it']],say:`<b>Day by day, language matters.</b> Students' disengagement increased on days when they perceived controlling language and commands, suppressed perspectives, or activities with little connection to their interests. On days when teachers were more considerate of their opinions, interests and preferences, or gave more room for questions, engagement and autonomous motivation went up. Autonomy-supportive language is informational and non-controlling: "could", "might", "consider", hints and suggestions. Controlling language pressures: "must", "should". Taking and validating students' perspectives, including their criticism and negative feelings, is at the core of autonomy-supportive teaching.`},
 {k:'ja',ic:'🎬',c:['Jang and colleagues (2016) randomly assigned college students to get','the same lesson either in the way they preferred (video clips and','class discussion) or in a non-preferred way (seatwork, worksheets).'],q:'What did the preferred way lead to?',o:[['More autonomy, engagement','and conceptual learning'],['More enjoyment but','less learning'],['No difference:','same content']],say:`<b>Build students' preferences into the lesson.</b> Students who received instruction in their preferred way experienced greater autonomy and, in turn, greater engagement and conceptual learning. Teachers can also design lessons around students' interests, or let students personalize activities. Because students were randomly assigned, this is causal evidence.`},
 {k:'ae',ic:'🙋',c:['So far the teacher did everything. But students can also speak up:','suggest, ask, say what they need. This is called','agentic engagement.'],q:'How do teachers tend to respond when students do this?',o:[['With more','autonomy support'],['With more','control'],['They do not','respond']],say:`<b>Students shape the classroom too.</b> Longitudinal evidence suggests that teachers respond to students' agentic engagement by increasing autonomy support, and that students afterwards experience enhanced autonomy, engagement and achievement. Autonomy-supportive teachers naturally encourage it, which creates a self-reinforcing cycle. Mind the hedge: the authors call this evidence preliminary, and say more is needed before recommending specific ways for teachers to foster agency.`}],
 end:['Autonomy support is a way of interacting: take the student\'s perspective,',' and help the student feel that the learning is their own choice.'],
 endOut:`<b>🏁 Six practices from Table 2</b>, plus rationales, which the chapter treats under value. The benefits of autonomy support seem to apply from preschool to graduate school and across ability levels, cultures and contexts, and research suggests it is equally or more effective among students of colour and low-income students.`,
 extras:[['📈 What autonomy support is linked to',`Greater feelings of autonomy and autonomous motivation; greater behavioural and emotional engagement and self-regulation for learning; greater self-esteem, vitality, life satisfaction and well-being; and academic achievement. A limitation the authors name: little is known about how to tailor autonomy support to particular subjects, contexts and populations.`],['🧒 Why adolescence matters',`The <b>stage-environment fit</b> perspective says school should fit the developmental stage. Adolescents need more autonomy, yet autonomy-supportive practices are used less in secondary than in elementary school. This lack of fit may account for the declines in motivation that longitudinal research keeps finding.`]]});

/* ---------- step 5 · value and interest ---------- */
SEQ('pracVal','pvOut',{title:'Support the feeling "this matters, this grabs me"',hook:'Hook: why · real world · my world · doing · devices',unit:'Case',
 draw(S){return PBOARD(S,['✨',['Value and','interest'],'#2f8a57','#e2f1e6',['Table 3']],[['ra','💡',['Rationales and','emphasis on purpose']],['ct','🌍',['Contextualized teaching','and learning']],['cr','🧬',['Culturally relevant /','responsive education']],['al','🛠️',['Active learning']],['dt','🥽',['Digital technology']]],{jr:'ra',br:'ra',sg:'ra',pl:['ct','al'],ce:'cr',vr:'dt'})},
 rounds:[
 {k:'jr',ic:'💡',c:['Jang (2008): before a statistics lesson, some undergraduates heard','how the content would help their personal and professional growth.','Others got the same lesson without that explanation.'],q:'What did the explanation do?',o:[['More engagement and more','conceptual learning'],['More engagement,','same learning'],['Nothing']],say:`<b>A rationale reveals hidden value.</b> Students who received the rationale were more engaged during the lesson and experienced greater conceptual learning. They seemed to benefit both because they experienced greater autonomy and because they perceived the activity as more important to themselves.`},
 {k:'br',ic:'🚫',c:['Not every reason works. A teacher wants to justify','a boring but necessary exercise.'],q:'Which reason can UNDERMINE motivation?',o:[['"Because everyone in the','7th grade learns this."'],['"It helps you help','people in your community."'],['"It connects to the goal','you told me about."']],say:`<b>Controlling rationales backfire.</b> Rationales that appeal to extrinsic goals (money, grades), to social norms ("because everyone in the 7th grade learns this") or to pressure ("do it because I said so"), or that take only the teacher's perspective, can undermine motivation. Effective rationales build on what students know, take the student's perspective, and show specifically and concretely how the activity relates to the student's own values, goals and life. Rationales that appeal to prosocial goals (community, helping others) or intrinsic goals are particularly effective.`},
 {k:'sg',ic:'✍️',c:['Leo has little interest in biology and little confidence in it.','Two options: the teacher tells him why biology is useful, or Leo','writes for himself how the material connects to his own life.'],q:'Which does the chapter call particularly effective for a student like Leo?',o:[['Writing his','own reasons'],['Being told','the reasons'],['Neither']],say:`<b>It depends on the student.</b> Directly communicated rationales tend to be most effective for students with high interest and competence. Self-generated value activities are particularly effective for students with low interest and competence, and among first-generation students of colour. Writing tasks in which students explain how the material is relevant to their lives increase perceived utility value, interest and performance (Hulleman et al., 2010). Focusing on relevance for daily life and helping-oriented goals, not only future careers, may extend the benefits to more students. (Leo is our example.)`},
 {k:'pl',ic:'🧙',c:['Parker and Lepper (1992): elementary school children worked with','maths materials. For some, the maths was embedded in a fantasy','setting; for others it was purely abstract.'],q:'Which children reported greater interest?',o:[['The fantasy','group'],['The abstract','group'],['No difference']],say:`<b>Contextualized teaching and learning.</b> Embedding content in meaningful or exciting contexts raised interest. Teachers can think of it as interdisciplinary, problem-based and applicable outside the classroom: investigating a community issue, or a lab in which students take the role of a professional solving a case. The key: it must be personally meaningful and connect with students' existing interests. Its neighbour in Table 3 is <b>active learning</b>: methods that make students think about what they are doing instead of passively receiving information (tap the chip at the end for more).`},
 {k:'vr',ic:'🥽',c:['Makransky and colleagues (2019): students learned laboratory safety','either in virtual reality or from a conventional safety manual.','The VR group reported more enjoyment and intrinsic motivation.'],q:'Will a novel technology keep students interested by itself?',o:[['No: it can trigger interest,','but may not maintain it'],['Yes: novelty','is enough']],say:`<b>A spark, not a fire.</b> Technology by itself can trigger interest because it is novel and exciting, but technology alone may not maintain interest. Digital tools will be most effective when combined with the other practices: emphasize purpose, contextualize, engage students actively. Remember triggered versus maintained situational interest from reading 1. The authors list digital technology among the promising practices with more limited causal evidence.`},
 {k:'ce',ic:'🧬',c:['Culturally relevant / responsive education (CRE) uses the cultural','experiences and perspectives of minoritized students as a medium','for teaching, for example analysing rap lyrics as poetry.'],q:'How strong is the research evidence for CRE, according to the authors?',o:[['Promising: mostly case studies,','some correlational evidence'],['Proven by many','randomized experiments'],['There is','none']],say:`<b>Promising, and honestly labelled.</b> Most of the support for CRE consists of case studies of exemplary classrooms; support beyond qualitative studies is limited, though its principles are consistent with other motivation theories and recent correlational evidence supports its use. CRE asks teachers to take an <b>asset-based</b> view: use students' existing strengths and welcome different forms and sources of knowledge. It also holds students to high academic standards.`}],
 end:['Students value and enjoy learning when they see why it matters, meet it in',' real and familiar contexts, and take an active part in it.'],
 endOut:`<b>🏁 Five practices from Table 3.</b> The chapter adds a sixth route without a new row: supporting autonomy also supports value and interest, because students who make their own choices experience content as more valuable and more interesting.`,
 extras:[['🛠️ Active learning',`Methods that make students actively think about what they are doing instead of passively receiving information: problem-solving in class, cooperative group work, demonstrations, peer-led sessions. In college biology classrooms randomly assigned to be enhanced with such practices, students reported higher situational interest and task value (Corkin et al., 2017). Teachers may find it most beneficial to use several strategies together. The benefits can be undermined if the activities are perceived as controlling or lack adequate structure.`],['📚 The theories behind value and interest',`<b>Expectancy-value theory:</b> attainment, intrinsic and utility value, and cost. <b>Self-determination theory:</b> helping students internalize learning behaviours so that they endorse them as their own. <b>Interest theories:</b> situational interest is the most responsive to the learning environment, and repeated arousal of situational interest has a positive effect on the development of individual interest. <b>Culturally relevant/responsive education</b>, committed to collective empowerment and social justice.`]]});

/* ---------- step 6 · growth mindset and mastery goals ---------- */
SEQ('pracGrow','pgOut',{title:'Support the feeling "I can grow, and I am here to learn"',hook:'Hook: the brain grows · causes I control · praise the process · a class about learning',unit:'Case',
 draw(S){return PBOARD(S,['🌱',['Growth mindset,','mastery goals'],'#a8854a','#f6eedd',['Table 4']],[['mt','🧠',['Mindset training']],['at','🔍',['Attributional training']],['pr','👏',['Praise for effort','and process']],['mg','🏫',['Mastery goal','structure']]],{si:'mt',md:'pr',gu:'pr',ar:'at',ko:'mg',ru:'mg'})},
 rounds:[
 {k:'si',ic:'🧠',c:['Mindset programmes teach students that intelligence can grow.','Sisk and colleagues (2018) combined the studies on such','programmes in a meta-analysis.'],q:'What did they find for achievement?',o:[['A small effect, only for','at-risk students'],['A large effect','for everyone'],['No effect','at all']],say:`<b>Small, and not for everyone.</b> Sisk et al. (2018) found a small positive main effect, with analyses suggesting that mindset interventions only benefit achievement for academically high-risk and economically disadvantaged students. The authors call the evidence on these programmes mixed. More recent studies indicate that mindset interventions may be protective for students from underrepresented groups such as Latinx students, but not consistently across outcomes and groups. Their balanced conclusion: there is some benefit, especially given the low cost, but the effects are relatively small, may only be useful for students already at risk, and may only work if the wider school context reinforces the message that intelligence is malleable.`},
 {k:'md',ic:'👏',c:['Mueller and Dweck (1998) compared praise for ability with','praise for effort in upper elementary students, and looked','at what happened after a failure.'],q:'After the failure, the children praised for ABILITY:',o:[['Persisted less and blamed','their ability'],['Persisted more: they','felt smart'],['Reacted the','same']],say:`<b>Person praise versus process praise.</b> Children who received ability-related praise placed more emphasis on performance goals relative to mastery goals; had decreased persistence, enjoyment and task performance after failure; and were more likely to attribute the failure to ability. <b>Person praise</b> (about characteristics such as being smart) promotes a fixed mindset; <b>process praise</b> (hard work, good strategies, focus, perseverance) promotes a growth mindset and resilience. An honest footnote in the chapter: these findings have not been fully replicated.`},
 {k:'gu',ic:'👶',c:['Gunderson and colleagues (2018) looked at how parents praised','their young children, and followed the children for years.'],q:'Children whose parents used more process praise:',o:[['Growth mindset 5 years on,','higher achievement after 7'],['Showed no','lasting effect'],['Became dependent','on praise']],say:`<b>Long-range effects.</b> When parents used process praise with young children, those children endorsed more incremental (growth) mindsets five years later and in turn had higher reading and mathematics achievement seven years later.`},
 {k:'ar',ic:'🔍',c:['Attributional retraining: after an exam, students watch older','students describe how they first failed and later succeeded,','once they saw their failures had causes they could control.'],q:'For which students is this especially beneficial?',o:[['Stereotype-threatened, or low','control or low achievement'],['High achievers who','already feel in control'],['It works equally','for all']],say:`<b>Change the explanation, change the motivation.</b> Students are trained to think about successes as controllable and failures as unstable. A professor then stresses controllable causes (insufficient effort, poor study strategies), and students consolidate it in a discussion or writing task. These studies suggest benefits for achievement, attribution patterns, mastery goals, expectancies and value, especially among students who may feel threatened by negative stereotypes (for example females in mathematics) or those with low perceived control or low prior achievement.`},
 {k:'ko',ic:'📝',c:['Koenka and colleagues (2021), a meta-analysis of feedback:','some students received grades only, others received','comments: more detailed feedback on their performance.'],q:'Which kind of feedback went with higher mastery goals?',o:[['Comments'],['Grades alone'],['No difference']],say:`<b>Comments beat grades.</b> Compared with no feedback, receiving grades was associated with endorsing performance goals but was unrelated to mastery goals. When students received comments versus grades alone, higher mastery goals were endorsed. This matches Ryan and Deci's point in reading 2 about informational versus controlling feedback.`},
 {k:'ru',ic:'🏫',c:['Two ways to evaluate the same class. Teacher A grades "on a curve":','your grade depends on how classmates did. Teacher B uses a rubric:','your work is compared with fixed standards.'],q:'Which practice fosters mastery goals?',o:[['B: the rubric'],['A: the curve'],['Both equally']],say:`<b>What the classroom rewards, students pursue.</b> Evaluation that emphasizes relative ability and social comparison (grading on a curve) highlights the need to <i>demonstrate</i> competence and fosters performance goals. Practices that focus on improvement and absolute standards (rubrics) signal that <i>developing</i> competence is valued and foster mastery goals. A <b>mastery goal structure</b> combines challenging, meaningful tasks; evaluation focused on progress; support for autonomy; and a positive socio-emotional climate. (Teachers A and B are our example.)`}],
 end:['Students aim to learn when they believe ability can grow, explain setbacks',' by causes they control, and sit in a class that values progress over rank.'],
 endOut:`<b>🏁 Four practices from Table 4.</b> The chapter treats attributions, mindsets and achievement goals together because they are closely related: performance goals, fixed (entity) beliefs and helpless attributions tend to occur together, and so do mastery goals, growth (incremental) beliefs and adaptive attributions.`,
 extras:[['🧩 How a mindset changes an attribution',`Framing intelligence as fixed or as able to grow changes what "ability" means as a cause. With an <b>entity</b> (fixed) view, attributing a result to ability means an internal, stable, uncontrollable cause. With an <b>incremental</b> (growth) view, the same attribution reflects an internal, unstable, controllable cause. Attributions to internal, controllable causes such as effort or strategy use are considered the most effective for engagement and learning.`],['🏫 The four parts of a mastery goal structure',`<b>Tasks:</b> varied, meaningful, appropriately challenging, with high cognitive demand plus scaffolding. <b>Evaluation and recognition:</b> improvement and absolute standards, evaluations kept private. <b>Autonomy and authority:</b> in a classroom with a higher mastery structure, students helped create the rules and had choice in daily routines; autonomy support may also buffer the effects of a performance-structured classroom. <b>Socio-emotional climate:</b> a positive tone, caring together with high expectations, collaboration and community; feeling connected can buffer the negative effects of a teacher's use of social comparison.`],['🎯 What the goals go with',`Mastery goals are positively associated with interest and self-efficacy, engagement, social and emotional well-being and, at least weakly, with achievement. Performance-avoidance goals relate to more negative affect and decreased engagement and achievement. Findings for performance-approach goals are mixed and somewhat controversial: related to achievement and interest, but also to anxiety and avoidance of help-seeking.`]]});

/* ---------- step 7 · relatedness and belonging ---------- */
SEQ('pracBel','pbOut',{title:'Support the feeling "I belong here"',hook:'Hook: know them · connect them · tell them · honour who they are',unit:'Case',
 draw(S){return PBOARD(S,['🤝',['Relatedness','and belonging'],'#4f6aa0','#e3ecf7',['Table 5']],[['tc','❤️',['Teacher-student','connections, community']],['gw','👥',['Collaboration and','group work']],['ms','📣',['Messages that','communicate belonging']],['cr','🧬',['Culturally relevant','education (again)']]],{my:'tc',wc:'ms',bi:'ms',gr:'tc',gp:'gw',cu:'cr'})},
 rounds:[
 {k:'my',ic:'🧐',c:['A once-popular idea: minoritized students, particularly','Black and Latinx students, do not value school.'],q:'What does research say about this idea?',o:[['It has been consistently','dispelled'],['It has been','confirmed'],['It has never','been studied']],say:`<b>Valuing school is not the problem.</b> Research has consistently dispelled this notion. Students of colour may identify with wanting to do well in school and yet still feel disconnected from school as an institution because of its unsupportive environment. Because of experiences with racism, both interpersonal and systemic (such as discriminatory disciplinary practices), minoritized students are more prone to lacking feelings of belonging in academic settings.`},
 {k:'wc',ic:'📈',c:['Belonging is related to outcomes such as staying in school,','persistence and grades.'],q:'For whom is that link often stronger?',o:[['Minoritized','students'],['White','students'],['Equally strong','for all']],say:`<b>Belonging matters for all, and often more for some.</b> Belongingness is often more strongly connected to positive academic outcomes, such as retention, persistence and GPA increases, for minoritized students than for white students (Walton &amp; Cohen, 2007, 2011). That is why this section of the chapter focuses on practices that support belonging particularly for Black, Latinx, Native and other students of colour.`},
 {k:'bi',ic:'📣',c:['A belonging intervention for first-year college students: they','are shown what are presented as survey results, and stories,','from older students about their own first year.'],q:'What is the core message of these materials?',o:[['Doubts about belonging are','common and they pass'],['Work harder and you','will fit in'],['Some groups simply','belong less']],say:`<b>Common and temporary.</b> The survey results indicate consistent improvement in belonging over time across social identities, with no differences between genders or races and ethnicities. That conveys that a lack of belonging is not a function of who you are, and that concerns about belonging are temporary. Reading testimonials of older students has also boosted first-generation college students' sense of belonging. Teachers can do the same in class: discuss belonging openly, show appreciation for all students, and let peers tell how their own doubts passed.`},
 {k:'gr',ic:'❤️',c:['Researchers compared how well different things predicted students\'','interest, engagement and achievement: teacher caring and','friendliness, or traits like grit and academic commitment.'],q:'What did one study find?',o:[['Teacher caring sometimes','predicted better'],['Grit always','predicted better'],['Neither predicted','anything']],say:`<b>Relationships are a serious predictor.</b> Teacher caring, friendliness and social support predict interest, engagement and achievement, sometimes even better than motivational characteristics like grit and academic commitment (Buskirk-Cohen &amp; Plants, 2019). Autonomy support is part of the key: students feel respected and cared for when teachers honour their autonomy and take their perspectives. The key to a positive relationship is psychological safety. Teacher caring may be especially effective for minoritized students, for females in male-dominated disciplines such as computer science, and for international students.`},
 {k:'gp',ic:'👥',c:['A teacher plans a group project and wants it to build','belonging, not frustration.'],q:'Which set-up does the research support?',o:[['Small groups, a common goal,','each member accountable'],['One large group,','one shared grade'],['Free groups, no','structure']],say:`<b>Design the collaboration.</b> What helps: setting common goals with adequate structure, creating smaller groups (pairs, three to four students), cultivating positive interdependence, facilitating competition <i>between</i> groups, and having some individual accountability. These promote positive relationships and active collaboration and discourage <b>social loafing</b> (letting others do the work). Simply working with other people, or talking with others about an activity, can also increase interest in it.`},
 {k:'cu',ic:'🧬',c:['Culturally relevant education returns in this section, now','as a way to build belonging.'],q:'Is there one correct way to practise it in class?',o:[['No: it must fit the students,','their age and their culture'],['Yes: a fixed','programme']],say:`<b>By definition, no single correct way.</b> What counts as culture differs by age and group: for Latinx fifth graders in one study, food, language and family were most salient; in a programme for Black high school students, camaraderie and collectivism. Common characteristics of effective CRE: acknowledging students' cultural competencies as strengths, co-constructing the classroom experience with students, and holding students to high academic standards. In one study, students who reported receiving more diverse content and feeling encouraged to learn about other cultures had higher grades (Byrd, 2016). Teachers may find it helpful to examine their own racial and ethnic identity; reflecting on one's privilege, biases and behaviours has been shown to create a more positive environment.`}],
 end:['Students engage when they feel connected and accepted: by a teacher who',' cares, by classmates they work with, and by a school that sees who they are.'],
 endOut:`<b>🏁 Three practices from Table 5, plus culturally relevant education.</b> The authors count practices to support relatedness among the promising ones with more limited causal evidence, and note that belonging interventions were largely conducted at college level, often outside ordinary lessons.`,
 extras:[['📚 The theories behind belonging',`High school students in one study wished for more meaningful relationships with teachers who, they felt, seemed to just teach. <b>Attachment theory:</b> early bonds with caregivers matter throughout life; children with a secure attachment show higher grades, school engagement, attention and self-confidence. <b>Self-determination theory:</b> relatedness is a basic need, and feeling connected lets students internalize the values of people close to them. <b>The belongingness hypothesis</b> (Baumeister and Leary): all humans have a pervasive drive to form and maintain lasting, positive relationships. Students who are rejected have few psychological resources left for schoolwork and may become aggressive or turn to bullying.`]]});

/* ---------- step 8 · use it, and its limits ---------- */
SEQ('pracUse','puOut',{title:'One classroom, different students: choose with care',hook:'Hook: combine · tailor · build bridges',unit:'Case',
 draw(S){const g=S.got;let s='';[['ov','🔗','Overlap: combine','one practice, several supports;','one need, several practices',['c1','c2']],['pr','🎯','Precision: tailor','the same practice lands','differently per student',['t1','t2']],['pa','🌉','Partnership','researchers working with','teachers and policy-makers',['p1']]].forEach((c,j)=>{const x=12+j*208,on=c[5].some(k=>g[k])||S.end;
   s+=BX(x,58,200,150,on?'#e3ecf7':'#fff',on?'#34466b':'#c9cfd9',on?2.2:1.4)+`<text x="${x+100}" y="100" ${mid} font-size="28">${c[1]}</text><text x="${x+100}" y="128" ${mid} class="t-b" font-size="12.5">${c[2]}</text><text x="${x+100}" y="152" ${mid} class="t-s" font-size="10.5">${on?c[3]:''}</text><text x="${x+100}" y="168" ${mid} class="t-s" font-size="10.5">${on?c[4]:''}</text>`});
  s+=BX(12,216,616,34,g.ev||S.end?'#f6eedd':'#fff',g.ev||S.end?'#c9a96e':'#c9cfd9',1.4,17)+`<text x="320" y="238" ${mid} font-weight="700" font-size="11" fill="${g.ev||S.end?'#a8854a':'#9aa3ad'}">${g.ev||S.end?'Promising, less causal evidence: agency · digital technology · relatedness practices · CRE':'How strong is the evidence?'}</text>`;return s},
 rounds:[
 {k:'t1',ic:'🎯',c:['Maya is confident in maths. She enjoys getting to choose her','tasks and hearing why a topic is important. Leo has limited','skills and little confidence. He gets the same treatment.'],q:'How might Leo experience the choices and the value messages?',o:[['As demoralizing, and lacking','in supportive care'],['Exactly as Maya','does'],['As even more','motivating']],say:`<b>The same practice can land differently.</b> Students who are confident in a domain might relish the opportunity to choose and benefit when a teacher gives a rationale. Such strategies may not be ideal for less confident students, who may experience the opportunities to choose and the value messages as demoralizing and lacking in supportive caring, in the context of their limited skills. (Maya and Leo are our names for the chapter's two kinds of student.)`},
 {k:'t2',ic:'📣',c:['A teacher tells a whole class: "You all belong here, and','your ability can grow." Some students have never doubted','either of those things.'],q:'For those students the message may:',o:[['Have little impact, or even','feel patronizing'],['Be just as','powerful'],['Harm their','grades']],say:`<b>Precision.</b> Messages that support belonging, assert that ability is malleable or convey high expectations can be particularly critical for minoritized and marginalized students, for whom belonging and competence may continuously be brought into question by societal forces. Among students who do not question their belonging or ability, such messages may have little impact, go unnoticed, or even feel patronizing. So support needs to be tailored to the motivational challenge a student is actually experiencing.`},
 {k:'c1',ic:'🔗',c:['The chapter recommended clear structure: expectations, rules,','norms and routines.'],q:'How is structure best delivered, according to the conclusion?',o:[['Together with autonomy support','and a supportive climate'],['On its own,','strictly'],['Only after belonging','is secured']],say:`<b>Practices work best in combination.</b> Structure is best delivered in combination with autonomy-supportive practices and an emotionally supportive climate that emphasizes that everyone belongs and is expected to succeed. Collaboration works best when structures guide it and support perceived competence. Digital technology is most likely to help when it is used to bring in other practices that support competence, autonomy or value.`},
 {k:'c2',ic:'🧩',c:['A teacher has found one practice that works well','and wants to rely on it.'],q:'Will a single practice usually be enough?',o:[['Rarely: motivation needs a','coordinated set'],['Yes, if it is the','right one']],say:`<b>Rarely.</b> One practice is seldom enough to cover what a whole class needs, or even what one student needs. The complexity of motivation often requires a coordinated set of conditions that support many interconnected forms of motivation. This is the practical version of reading 1's conclusion: several motivations work together inside one person.`},
 {k:'ev',ic:'🔬',c:['The authors mostly chose practices with well-established','evidence, including randomized experiments. But they flag','a few as promising, with more limited causal evidence.'],q:'Which of these is on the "promising" list?',o:[['Encouraging','student agency'],['Providing','choices'],['Clear classroom','structure']],say:`<b>Know which is which.</b> Promising practices with more limited causal evidence, or still needing research on how to use them in class: encouraging agency, using digital technology, practices to support relatedness, and culturally relevant education. Even so, the authors judge that there is broad enough support for the recommended practices to justify using them, especially in a multifaceted approach that considers the particular students.`},
 {k:'p1',ic:'🌉',c:['The chapter ends with a task for researchers themselves.'],q:'What do the authors ask motivation researchers to do?',o:[['Work with teachers and','policy-makers; co-design'],['Publish more','theory'],['Leave practice','to teachers']],say:`<b>Build the bridge.</b> The authors see a pressing need for researchers to work closely with educators and policy-makers, so that motivating instruction becomes a routine part of teaching. They suggest starting from the challenges teachers and students report, offering workshops, interventions or consulting (free of charge, particularly for public schools), and co-designing approaches with teachers. Their aim: motivating instruction as the norm, not the exception.`}],
 end:['Three closing themes: practices overlap and work best together; they must',' be tailored to the student; and research has to reach the classroom.'],
 endOut:`<b>🏁 Universal, but not one size fits all.</b> Most of the recommended practices are likely to have benefits regardless of the student or circumstance. Yet to maximize the benefits, support often needs to be tailored to the motivational challenges students are experiencing, and several practices need to be coordinated.`,
 extras:[]});

Object.assign(TT,{
'r-prac-1':{fit:'Readings 1 and 2 explained what makes a student start and keep going. This chapter asks the question from the other side of the desk: what can the teacher do about it?',
 key:'Unlike intelligence, motivation is <b>influenced by the educational environment</b>. That is the good news the whole chapter rests on, and five sets of practices follow from it.',
 think:'A thermostat versus a thermometer. Intelligence is closer to a thermometer reading: you can measure it, but a teacher cannot easily change it. Motivation is more like a thermostat: the classroom can turn it up or down.',
 friend:'"A lot of students are disengaged, and teachers worry about it. This chapter says motivation is something a classroom can change, and it collects the teaching practices with the best evidence into five groups."',
 hook:'<b>Can · own · matters · grow · belong.</b> Five supports.',
 tip:'This chapter is organized by what the teacher supports, not by theory. For an exam, be able to go both ways: from a practice to the kind of motivation it supports, and from a kind of motivation to two or three practices.'},
'r-prac-2':{fit:'If the theme asks what keeps a student going, this map is the teacher\'s short list of answers: five feelings to support, each with its own table of practices.',
 key:'The five categories are a deliberate simplification, and the practices <b>overlap</b>: one practice often supports several kinds of motivation.',
 think:'Five dials on a mixing desk. A sound engineer rarely moves just one, and moving one changes how the others sound.',
 friend:'"Teachers can support five things: that students feel able, feel it is their own choice, see value and interest, believe they can grow and aim to learn, and feel they belong. Most practices help with more than one."',
 hook:'<b>Can · own · matters · grow · belong.</b>',
 tip:'When a question asks which motivation a practice supports, give the primary one from the tables and add one "can also support". That shows you know the overlap.'},
'r-prac-3':{fit:'Reading 1 said a student starts and continues when she believes she can. This step shows how a classroom builds that belief.',
 key:'Perceived competence grows from <b>real mastery of appropriately challenging work</b>, made possible by structure, scaffolding and informative feedback. Making work easy does not build it.',
 think:'A climbing wall with coloured routes. Clear routes (structure), a route just above your level (challenge), a belayer who gives tips (scaffolding and feedback), watching someone your size climb it (modeling), and learning how to read a route yourself (self-regulation).',
 friend:'"To make students feel capable, do not make things easy. Be clear about what is expected, give work that stretches them with help to get there, tell them what they did well and how to improve, show them people like them who struggled and made it, and teach them how to study."',
 hook:'<b>Clear · stretching · informative · someone like me · strategies.</b>',
 tip:'Two findings carry a "for whom": wise feedback (strongest for African American students, especially with mistrust) and strategy instruction (strongest for students with lower initial grades).'},
'r-prac-4':{fit:'Reading 2 argued that students keep going when the reason for acting is their own. This step lists what a teacher does to make that happen.',
 key:'What matters is the <b>experience of autonomy</b>, not the number of choices. Choice is one tool among six, and it can backfire when it is controlling, overwhelming or beyond the student\'s competence.',
 think:'A good restaurant. The waiter asks what you like, explains the dishes, recommends without pushing, and the menu is short enough to choose from. Two hundred dishes with no explanation is not freedom, it is a burden.',
 friend:'"Supporting autonomy is mostly about taking the student\'s point of view: offer real choices, listen, build their interests into lessons, say \'you could\' instead of \'you must\', and let students help shape the class. But too many choices, or choices they cannot judge, do not help."',
 hook:'<b>Offer · listen · build in · invite · do not push · let them shape it.</b>',
 tip:'The sentence to remember: choice opportunities, choosing, and experiencing autonomy are not synonymous. Exam items like to test when choice does not work.'},
'r-prac-5':{fit:'A student who believes she can and feels free may still ask "why bother?". This step is about giving learning a point, and a pull.',
 key:'Value has to be <b>the student\'s own</b>. A reason works when it is concrete and connected to the student\'s goals; for students low in interest and confidence, the chapter calls reasons they generate themselves particularly effective.',
 think:'Selling a hiking trip. To a keen hiker you can simply describe the route. To someone who never hikes, you ask what they enjoy, and let them discover that the trip has it.',
 friend:'"To make learning feel worthwhile: explain why it matters in terms the student cares about, tie it to real life and to the student\'s own culture, get students doing things, and use technology as a spark. And for students who are not interested yet, let them work out the relevance themselves."',
 hook:'<b>Why · real world · my world · doing · devices.</b>',
 tip:'Know the four kinds of rationale that can undermine motivation: extrinsic goals (money, grades), social norms, pressure, and reasons that take only the teacher\'s perspective.'},
'r-prac-6':{fit:'Keeping going after a setback depends on what the setback means to the student. This step is about teaching students that ability grows and that the class is about learning.',
 key:'The message "you can grow" works best when the <b>whole classroom</b> says it: in praise, in how failure is explained, and in how work is evaluated. A mindset lesson alone has small effects.',
 think:'A gym. A poster saying "muscles grow with training" helps a little. A gym where trainers praise your form, track your own progress and do not rank you against the person next to you helps a lot.',
 friend:'"Teach that ability can grow, help students explain failure by things they can change, praise effort and strategy instead of talent, and run the class so that improvement counts more than rank. Mindset programmes work a bit, and possibly only for students already at risk."',
 hook:'<b>The brain grows · causes I control · praise the process · a class about learning.</b>',
 tip:'This step has the most hedges of the chapter: mindset evidence is "mixed", the effect is small, and the praise study has "not been fully replicated". Report them.'},
'r-prac-7':{fit:'A student can feel able, free and interested, and still drift away if she feels she does not belong. This is the fifth support.',
 key:'Belonging is not a soft extra. It predicts engagement and achievement, <b>often more strongly for minoritized students</b>, and a teacher builds it through relationships, well-designed collaboration and explicit messages.',
 think:'Joining a sports club. You stay if the coach knows your name, if you get paired with teammates for drills, if someone tells you everyone feels awkward in the first weeks, and if the club makes room for who you are.',
 friend:'"Students need to feel they belong. Teachers build that by really knowing students, organizing group work well, saying out loud that doubts about fitting in are normal and pass, and respecting students\' cultures. It matters most for students who have reasons to doubt they belong."',
 hook:'<b>Know them · connect them · tell them · honour who they are.</b>',
 tip:'The belonging message has two parts: doubts are <b>common</b> and they are <b>temporary</b>. Both words belong in an answer.'},
'r-prac-8':{fit:'The theme\'s question has no single answer for every student. The chapter\'s conclusion is about choosing and combining the supports for the students in front of you.',
 key:'<b>Universal but not uniform.</b> There is some degree of universality: most practices are likely to have benefits whoever the student is. But they must be combined and tailored to the motivational challenge a particular student faces.',
 think:'A doctor and five good medicines. All five are safe and useful, but a good doctor asks what is wrong with this patient first, and often prescribes two together.',
 friend:'"The five kinds of practice overlap and work best together. They help nearly everyone, but which one a student needs depends on that student: a belonging message means a lot to someone who doubts she belongs and little to someone who never did."',
 hook:'<b>Combine · tailor · build bridges.</b>',
 tip:'For a case question: first diagnose which of the five supports the student is missing, then choose practices from that table, then add one from another table that reinforces it.'}
});
Object.assign(ZERO,{
'r-prac-1':'Start here. This is a <b>handbook chapter</b>, like reading 1, and two of its authors wrote reading 1. <b>Adaptive motivation</b> means motivation that helps learning. <b>Engagement</b> is behavioural, emotional and cognitive involvement in a task. An <b>instructional practice</b> is something a teacher does in teaching. <b>Evidence-based</b> means supported by research. <b>Minoritized</b> or <b>marginalized</b> students belong to groups that society has pushed to the edge or treated as lesser. <b>In the picture:</b> on the left, the problem the chapter starts from. In the middle, its good news: unlike intelligence, motivation responds to the classroom. On the right, the plan: five kinds of motivation to support, each with a table of practices, then three closing themes.',
'r-prac-2':'This step gives you the map of the chapter. It has five main sections, each built the same way: the theories behind one kind of motivation, then a table of teaching practices that primarily support it, then the evidence. <b>In the picture:</b> five tiles, each with a feeling in the student\'s own words. Five teacher practices come by: tap the tile that each practice mainly supports. The tile then shows the chapter\'s name for that kind of motivation and the number of its table.'
});
Object.assign(GLOSS,{
compbel:['Competence beliefs','Positive self-assessments of one\'s ability and likelihood of succeeding at a task. Includes self-efficacy, achievement expectancies and academic self-concept.'],
scaffold:['Scaffolding','Temporary support that helps a student meet a challenge: hints, tips, cues, examples, guidance, or breaking a task into manageable pieces.'],
wisefb:['Wise feedback','Critical feedback framed as coming from high expectations and from confidence that the student can meet them (Yeager et al., 2014).'],
selfreg:['Self-regulation instruction','Teaching students strategies for managing their own learning: goal-setting, summarizing, organizing, monitoring progress, self-talk.'],
agentic:['Agentic engagement','Students deliberately trying to enrich their learning by offering input and working with the teacher to make lessons more interesting or valuable (Reeve, 2013).'],
rationale:['Rationale','An explanation of why an activity is useful or important.'],
ctl:['Contextualized teaching and learning','Embedding subject content in meaningful, real-world or exciting situations that connect to students\' interests.'],
cre:['Culturally relevant/responsive education (CRE)','Using the cultural characteristics, experiences and perspectives of minoritized and marginalized students as a medium for teaching them more effectively.'],
activel:['Active learning','Teaching methods that make students actively think about what they are doing, instead of passively receiving information.'],
growthm:['Growth (incremental) mindset','The belief that ability can develop through effort, effective strategies and instruction. Its opposite, a fixed (entity) mindset, holds that ability is innate and unchangeable.'],
mgs:['Mastery goal structure','A classroom whose tasks, evaluation, authority and climate signal that developing competence is what counts.'],
belong:['Belonging','The extent to which a person feels connected to others in their life; in school, feeling accepted and represented.'],
sloaf:['Social loafing','Putting in less effort in a group because others will do the work.'],
stfit:['Stage-environment fit','The idea that a school environment should match the developmental needs of students at that age.']
});
